<div class="cb-modal" id="cbShareModal" aria-hidden="true"><div class="cb-modal-card cb-modal-md"><div class="cb-modal-head"><h3><i class="fas fa-share-nodes"></i> <span id="cbShareTitle">Groom Registration</span></h3><button class="cb-modal-close" type="button" data-cb-close>&times;</button></div><div class="cb-modal-body"><div class="cb-share-grid"><div class="cb-qr-box" id="cbQrBox"></div><div><p class="cb-help">The groom can scan this QR or open the link to complete the couple's wedding details. If linked to an existing wedding, the submission updates that record.</p><div class="cb-link-copy"><input class="cb-input" id="cbShareUrl" readonly><button class="cb-btn cb-btn-outline" id="cbCopyLink" type="button"><i class="fas fa-copy"></i> Copy</button></div><div class="cb-actions" style="margin-top:12px"><button class="cb-btn cb-btn-primary" id="cbNativeShare" type="button"><i class="fas fa-share-nodes"></i> Share Link</button><button class="cb-btn cb-btn-success" id="cbDownloadQr" type="button"><i class="fas fa-download"></i> Download QR</button></div></div></div></div><div class="cb-modal-foot"><button class="cb-btn cb-btn-outline" type="button" data-cb-close>Close</button></div></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));const form=$('#weddingForm');$('[data-open-add]')?.addEventListener('click',()=>{form.reset();form.elements.id.value='';$('#weddingModalTitle').textContent='Add Wedding Record';CBModal.open('#weddingFormModal')});$('[data-open-link]')?.addEventListener('click',()=>{const f=$('#groomLinkForm');f.reset();f.elements.wedding_id.value='';f.elements.max_uses.value='1';$('#groomLinkHint').textContent='Create a general link, or use the QR button on a wedding row to link the groom directly to that record.';CBModal.open('#weddingLinksModal')});$$('.js-groom-link').forEach(b=>b.addEventListener('click',()=>{const f=$('#groomLinkForm');f.reset();f.elements.wedding_id.value=b.dataset.id;f.elements.recipient_name.value=b.dataset.name||'';f.elements.recipient_phone.value=b.dataset.phone||'';f.elements.label.value=(b.dataset.name||'Groom')+' wedding registration';f.elements.max_uses.value='1';$('#groomLinkHint').textContent='This link will update wedding record #'+b.dataset.id+' when the groom submits it.';CBModal.open('#weddingLinksModal')}));$$('.member-select').forEach(s=>s.addEventListener('change',()=>{const o=s.options[s.selectedIndex],t=form.elements[s.dataset.nameTarget];if(o?.dataset.name&&t&&!t.value)t.value=o.dataset.name}));$$('.js-edit').forEach(b=>b.addEventListener('click',()=>{const r=JSON.parse(b.dataset.record);form.reset();Object.keys(r).forEach(k=>{if(form.elements[k])form.elements[k].value=r[k]??''});$('#weddingModalTitle').textContent='Edit Wedding Record';CBModal.open('#weddingFormModal')}));const labels={register_no:'Register No.',wedding_date:'Wedding Date',wedding_time:'Wedding Time',venue:'Venue',status:'Status',groom_name:'Groom',groom_phone:'Groom Phone',groom_address:'Groom Address',groom_father:'Groom Father',groom_mother:'Groom Mother',bride_name:'Bride',bride_phone:'Bride Phone',bride_address:'Bride Address',bride_father:'Bride Father',bride_mother:'Bride Mother',ceremony_type:'Ceremony Basis',banns_date_1:'1st Banns',banns_date_2:'2nd Banns',banns_date_3:'3rd Banns',marriage_licence_no:'Licence No.',certificate_no:'Certificate No.',witness_1:'Witness 1',witness_2:'Witness 2',officiant:'Officiating Minister',assisting_minister:'Assisting Minister',scripture_theme:'Scripture / Theme',vows_text:'Vows / Declaration',remarks:'Remarks'};const esc=v=>String(v??'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));$$('.js-view').forEach(b=>b.addEventListener('click',()=>{const r=JSON.parse(b.dataset.record);$('#weddingView').innerHTML=Object.entries(labels).map(([k,l])=>`<div class="cb-view-item ${['venue','vows_text','remarks'].includes(k)?'span-2':''}"><strong>${l}</strong><span>${esc(r[k]||'-')}</span></div>`).join('');CBModal.open('#weddingViewModal')}));});</script>

<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script>
<script>
(function(){
 const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
 function openModal(id){const m=typeof id==='string'?$(id):id;if(!m)return;m.classList.add('show');m.setAttribute('aria-hidden','false');document.body.classList.add('cms-modal-open');}
 function closeModal(m){if(!m)return;m.classList.remove('show');m.setAttribute('aria-hidden','true');if(!$('.cb-modal.show'))document.body.classList.remove('cms-modal-open');}
 $$('[data-cb-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.closest('.cb-modal'))));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){const m=$('.cb-modal.show');if(m)closeModal(m);}});
 // intentionally no backdrop-click close, matching Add Member behavior
 window.CBModal={open:openModal,close:closeModal};
 window.CBShare=function(url,title){
   const input=$('#cbShareUrl'), qr=$('#cbQrBox'), heading=$('#cbShareTitle'); if(input)input.value=url;if(heading)heading.textContent=title||'Registration Link';if(qr){qr.innerHTML='';if(window.QRCode){new QRCode(qr,{text:url,width:220,height:220,correctLevel:QRCode.CorrectLevel.H});}else{qr.innerHTML='<small>QR library unavailable. Use the link below.</small>';}}
   openModal('#cbShareModal');
 };
 $('#cbCopyLink')?.addEventListener('click',async function(){const i=$('#cbShareUrl');if(!i)return;try{await navigator.clipboard.writeText(i.value);this.innerHTML='<i class="fas fa-check"></i> Copied';setTimeout(()=>this.innerHTML='<i class="fas fa-copy"></i> Copy',1600);}catch(e){i.select();document.execCommand('copy');}});
 $('#cbNativeShare')?.addEventListener('click',async function(){const url=$('#cbShareUrl')?.value||'';if(navigator.share){try{await navigator.share({title:$('#cbShareTitle')?.textContent||'Registration Link',url});}catch(e){}}else{$('#cbCopyLink')?.click();}});
 $('#cbDownloadQr')?.addEventListener('click',function(){const box=$('#cbQrBox');if(!box)return;const canvas=box.querySelector('canvas'),img=box.querySelector('img');let src=canvas?canvas.toDataURL('image/png'):(img?img.src:'');if(!src)return;const a=document.createElement('a');a.href=src;a.download='registration-qr.png';document.body.appendChild(a);a.click();a.remove();});
})();
</script>
<?php if($share):?><script>document.addEventListener('DOMContentLoaded',()=>CBShare(<?= json_encode($share['url']) ?>,<?= json_encode($share['title']) ?>));</script><?php endif;?>
<?php endif;?></div></div><?php include '../includes/footer.php';?>
